    shipping_group = None
    for gname in ["Shipping Address", "Ship to", "Shipping", "Ship To"]:
        grp_loc = page.get_by_role("group", name=gname)
        if await count(grp_loc) > 0:
            shipping_group = grp_loc.first()
            break

    # If there's a 'Change' link/button scoped inside the shipping group, click it to enable editing
    if shipping_group is not None:
        if await count(shipping_group.get_by_role("link", name="Change")) > 0:
            await shipping_group.get_by_role("link", name="Change").first().click()
        elif await count(shipping_group.get_by_role("button", name="Change")) > 0:
            await shipping_group.get_by_role("button", name="Change").first().click()
    else:
        # Try a few global fallbacks for entering address edit mode
        if await count(page.get_by_role("link", name="Change")) > 0:
            await page.get_by_role("link", name="Change").first().click()
        elif await count(page.get_by_role("button", name="Change")) > 0:
            await page.get_by_role("button", name="Change").first().click()
        elif await count(page.get_by_role("link", name="Edit")) > 0:
            await page.get_by_role("link", name="Edit").first().click()
        elif await count(page.get_by_role("button", name="Edit")) > 0:
            await page.get_by_role("button", name="Edit").first().click()

    # Wait a moment for any edit UI/modal to appear
    await page.wait_for_load_state("networkidle")

    # Determine a scope for address fields: prefer the shipping_group if available, otherwise global
    scope = shipping_group if shipping_group is not None else page

    # Helper to try filling a textbox by several accessible names scoped to 'scope'
    async def try_fill_textbox_scoped(names, value):
        for n in names:
            loc = scope.get_by_role("textbox", name=n)
            if await count(loc) > 0:
                await loc.first().fill(value)
                return True
        return False

    # Street: Magento often exposes multiple textboxes with the same name 'Street'
