                        break
                    except Exception:
                        pass
    if not region_filled:
        await try_fill_textbox_scoped(["State/Province", "Region", "State"], "Texas")

    # Postcode / Zip
    await try_fill_textbox_scoped(["Zip/Postal Code", "Zip", "Postal Code", "Postcode"], "75201")

    # Country: combobox preferred
    country_filled = False
    for cname in ["Country", "Country/Region"]:
        cb = scope.get_by_role("combobox", name=cname)
        if await count(cb) > 0:
            try:
                await cb.first().select_option(value="US")
            except Exception:
                try:
                    await cb.first().select_option(label="United States")
                except Exception:
                    pass
            country_filled = True
            break

