async def act(page):
    # Navigate directly to the order view for order #301 using a leading-relative path
    await page.goto("/index.php/admin/sales_order/view/order_id/301/")
    await page.wait_for_load_state("networkidle")

    # Helper to safely get count
    async def count(locator):
        return await locator.count()

    # Try to find the shipping address group (several possible names) to scope subsequent actions
    shipping_group = None
    for gname in ["Shipping Address", "Ship to", "Shipping", "Ship To"]:
        grp_loc = page.get_by_role("group", name=gname)
        if await count(grp_loc) > 0:
            shipping_group = grp_loc.first()
            break

    # If there's a 'Change' link/button scoped inside the shipping group, click it to enable editing
    if shipping_group is not None:
        if await count(shipping_group.get_by_role("link", name="Change")) > 0:
            await shipping_group.get_by_role("link", name="Change").first().click()
        elif await count(shipping_group.get_by_role("button", name="Change")) > 0:
            await shipping_group.get_by_role("button", name="Change").first().click()
    else:
        # Try a few global fallbacks for entering address edit mode
        if await count(page.get_by_role("link", name="Change")) > 0:
            await page.get_by_role("link", name="Change").first().click()
        elif await count(page.get_by_role("button", name="Change")) > 0:
            await page.get_by_role("button", name="Change").first().click()
        elif await count(page.get_by_role("link", name="Edit")) > 0:
            await page.get_by_role("link", name="Edit").first().click()
        elif await count(page.get_by_role("button", name="Edit")) > 0:
            await page.get_by_role("button", name="Edit").first().click()

    # Wait a moment for any edit UI/modal to appear
    await page.wait_for_load_state("networkidle")

    # Determine a scope for address fields: prefer the shipping_group if available, otherwise global
    scope = shipping_group if shipping_group is not None else page

    # Helper to try filling a textbox by several accessible names scoped to 'scope'
    async def try_fill_textbox_scoped(names, value):
        for n in names:
            loc = scope.get_by_role("textbox", name=n)
            if await count(loc) > 0:
                await loc.first().fill(value)
                return True
        return False

    # Street: Magento often exposes multiple textboxes with the same name 'Street'
    # Try to fill the first street textbox and the second if present
    street_loc = scope.get_by_role("textbox", name="Street")
    if await count(street_loc) > 0:
        # fill first line
        await street_loc.nth(0).fill("321 Birch Boulevard")
        # fill second line if exists
        if await count(street_loc) > 1:
            await street_loc.nth(1).fill("Suite 200")
        else:
            # try common alternate name for second line
            alt = scope.get_by_role("textbox", name="Street Address")
            if await count(alt) > 0:
                await alt.first().fill("Suite 200")
    else:
        # fallback: try several possible labels
        filled = False
        for candidate in [["Street Address", "Address"], ["Address 1", "Address 2"]]:
            for name in candidate:
                loc = scope.get_by_role("textbox", name=name)
                if await count(loc) > 0:
                    await loc.first().fill("321 Birch Boulevard")
                    # try to fill second textbox if present
                    if await count(loc) > 1:
                        await loc.nth(1).fill("Suite 200")
                    filled = True
                    break
            if filled:
                break
        # final fallback: fill the first two textboxes on the page
        if not filled and await count(scope.get_by_role("textbox")) >= 1:
            await scope.get_by_role("textbox").nth(0).fill("321 Birch Boulevard")
            if await count(scope.get_by_role("textbox")) >= 2:
                await scope.get_by_role("textbox").nth(1).fill("Suite 200")

    # City
    await try_fill_textbox_scoped(["City", "Town/City", "City/Town"], "Dallas")

    # Region/State: try combobox first (select), then textbox
    region_names = ["State/Province", "Region/State", "Region", "State"]
    region_filled = False
    for rn in region_names:
        cb = scope.get_by_role("combobox", name=rn)
        if await count(cb) > 0:
            try:
                await cb.first().select_option(label="Texas")
                region_filled = True
                break
            except Exception:
                try:
                    await cb.first().select_option(value="TX")
                    region_filled = True
                    break
                except Exception:
                    # try a more verbose label
                    try:
                        await cb.first().select_option(label="TX - Texas")
                        region_filled = True
                        break
                    except Exception:
                        pass
    if not region_filled:
        await try_fill_textbox_scoped(["State/Province", "Region", "State"], "Texas")

    # Postcode / Zip
    await try_fill_textbox_scoped(["Zip/Postal Code", "Zip", "Postal Code", "Postcode"], "75201")

    # Country: combobox preferred
    country_filled = False
    for cname in ["Country", "Country/Region"]:
        cb = scope.get_by_role("combobox", name=cname)
        if await count(cb) > 0:
            try:
                await cb.first().select_option(value="US")
            except Exception:
                try:
                    await cb.first().select_option(label="United States")
                except Exception:
                    pass
            country_filled = True
            break

    # Click the Save/Update button for the address. Prefer scoped buttons inside the address group/modal.
    saved = False
    # Try common save button names inside scope
    for btn_name in ["Save Address", "Save", "Update Address", "Update"]:
        btn = scope.get_by_role("button", name=btn_name)
        if await count(btn) > 0:
            # If the button is within the shipping_group or other group, use the full path (we already scoped to 'scope')
            await btn.first().click()
            saved = True
            break

    # Global fallbacks: try top-level Save/Update buttons
    if not saved:
        for btn_name in ["Save Address", "Save", "Update Address", "Update"]:
            btn = page.get_by_role("button", name=btn_name)
            if await count(btn) > 0:
                await btn.first().click()
                saved = True
                break

    # Wait for changes to apply
    await page.wait_for_load_state("networkidle")
    return
